sysauto_script.script:
var assetGr = new GlideRecord('x_2053322_smartnes_asset');
assetGr.addQuery('maintenance_enabled', true);
assetGr.addQuery('next_maintenance', '<=', new GlideDateTime());
assetGr.query();

while(assetGr.next()) {
  // Duplicate Protection
  var dupCheck = new GlideRecord('x_2053322_smartnes_task');
  dupCheck.addQuery('asset_ref', assetGr.getUniqueValue());
  dupCheck.addQuery('task_type', 'Preventive Maintenance');
  dupCheck.addEncodedQuery('status!=Completed^status!=Rejected');
  dupCheck.query();

  if (!dupCheck.hasNext()) {
    var taskGr = new GlideRecord('x_2053322_smartnes_task');
    taskGr.initialize();
    taskGr.asset_ref = assetGr.getUniqueValue();
    taskGr.task_type = 'Preventive Maintenance';
    taskGr.status = 'New';

    // Add dummy complaint ref if schema mandates it (or we can just leave it blank since it's an Asset task)
    // We will leave complaint_ref empty.

    taskGr.insert();

    // Fire Notification Event (To Facility Manager)
    gs.eventQueue('x_2053322_smartnes.maintenance.due', assetGr, assetGr.getUniqueValue(), '');
  }
}
